1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	};
10	
11	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
12	
13	export type ScenarioResult = { premium: number };
14	
15	export type ScenarioOutcome = { results: ScenarioResult[] };
16	
17	type Item = { type: string };
18	
19	type Scenario = { steps: { items: Item[] }[] };
20	
21	const basePremiumOf = (item: Item): number =>
22	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
23	
24	// Adds the surcharge as a separate term rather than scaling by 1.1, because
25	// `100 * 1.1` is 115.00000000000001 in binary floating point.
26	const withFirstInsuranceSurcharge = (amount: number): number =>
27	  amount + amount * FIRST_INSURANCE_SURCHARGE_RATE;
28	
29	const quotePremium = (items: Item[]): number => {
30	  const basePremium = items.reduce<number>(
31	    (total, item) => total + basePremiumOf(item),
32	    0,
33	  );
34	
35	  // Rounded in the MHPCO's favour: premiums round up.
36	  return Math.ceil(withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE);
37	};
38	
39	export const runScenario = (scenario: unknown): ScenarioOutcome => {
40	  const { steps } = scenario as Scenario;
41	
42	  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));
43	
44	  return { results };
45	};
