// Amounts are rounded in the MHPCO's favour: premiums (charged to the
// customer) round up.
const roundPremiumInMHPCOsFavour = (amount: number): number =>
  Math.ceil(amount);

const quotePremium = (items: Item[]): number => {
  const basePremium = items.reduce<number>(
    (total, item) => total + basePremiumOf(item),
    0,
  );

  return roundPremiumInMHPCOsFavour(
    withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE,
  );
};
